import{_ as n,o as e,c as a,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Feature Workflow — spec → plan → task → test","description":"","frontmatter":{},"headers":[],"relativePath":"rule/feature-workflow.md","filePath":"rule/feature-workflow.md"}'),o={name:"rule/feature-workflow.md"};function s(i,t,h,r,l,d){return e(),a("div",null,[...t[0]||(t[0]=[c(`<h1 id="feature-workflow-—-spec-→-plan-→-task-→-test" tabindex="-1">Feature Workflow — spec → plan → task → test <a class="header-anchor" href="#feature-workflow-—-spec-→-plan-→-task-→-test" aria-label="Permalink to &quot;Feature Workflow — spec → plan → task → test&quot;">​</a></h1><p>&gt; <strong>Áp dụng cho toàn bộ các repo code trong hệ thống BrandHub:</strong> &gt; <code>brandhub-ai-service</code>, <code>brandhub-api-gateway</code>, <code>brandhub-business-service</code>, &gt; <code>brandhub-mobile-app</code>, <code>brandhub-publisher-service</code>, <code>brandhub-web-dashboard</code>. &gt; &gt; File này là <strong>nguồn sự thật duy nhất</strong>. Mỗi repo khác chỉ có 1 pointer trỏ về đây &gt; (trong <code>CLAUDE.md</code>). Muốn sửa quy trình → sửa file này, không sửa từng repo.</p><h2 id="_1-muc-đich" tabindex="-1">1. Mục đích <a class="header-anchor" href="#_1-muc-đich" aria-label="Permalink to &quot;1. Mục đích&quot;">​</a></h2><p>Mọi tính năng phát triển trong hệ thống phải đi qua <strong>4 tài liệu tuần tự</strong> trước khi viết code. Điều này đảm bảo: đúng nghiệp vụ, có kế hoạch rõ, có task phân rã, có test kiểm chứng — trước khi Claude AI (hoặc dev) bắt tay vào làm. Tránh &quot;code mò&quot;, tránh làm lan man, tránh làm lại nhiều lần.</p><h2 id="_2-cau-truc-thu-muc-feature" tabindex="-1">2. Cấu trúc thư mục feature <a class="header-anchor" href="#_2-cau-truc-thu-muc-feature" aria-label="Permalink to &quot;2. Cấu trúc thư mục feature&quot;">​</a></h2><p><strong>Vị trí bắt buộc:</strong> <code>brandhub-infrastructure/docs/feature/</code> — TẬP TRUNG, không đặt trong <code>docs/feature/</code> của từng repo con (<code>brandhub-web-dashboard</code>, <code>brandhub-mobile-app</code>, ...). Lý do giống <code>feature-workflow.md</code> — infra là nguồn sự thật duy nhất, tránh doc phân tán và mất đồng bộ giữa các repo khi nhiều người cùng làm feature liên quan nhiều service.</p><p>Mỗi tính năng là <strong>một thư mục</strong>, chứa đúng 4 file bắt buộc:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brandhub-infrastructure/docs/feature/&lt;ten-tinh-nang&gt;/</span></span>
<span class="line"><span>├── spec.md   # Đặc tả nghiệp vụ — LÀM TRƯỚC</span></span>
<span class="line"><span>├── plan.md   # Kế hoạch triển khai kỹ thuật</span></span>
<span class="line"><span>├── task.md   # Phân rã công việc (checklist thực thi)</span></span>
<span class="line"><span>└── test.md   # Kịch bản / test case kiểm chứng</span></span></code></pre></div><ul><li>Thư mục đặt theo <strong>tên tính năng</strong> (kebab-case, tiếng Anh), không theo mã UC, không phân theo tên repo. Vd: <code>multi-method-login</code>, <code>content-scheduler</code>.</li><li>Mỗi file có <strong>trách nhiệm duy nhất</strong>, không trộn lẫn.</li></ul><h2 id="_3-noi-dung-tung-file" tabindex="-1">3. Nội dung từng file <a class="header-anchor" href="#_3-noi-dung-tung-file" aria-label="Permalink to &quot;3. Nội dung từng file&quot;">​</a></h2><h3 id="spec-md-—-đac-ta-nghiep-vu" tabindex="-1">spec.md — Đặc tả nghiệp vụ <a class="header-anchor" href="#spec-md-—-đac-ta-nghiep-vu" aria-label="Permalink to &quot;spec.md — Đặc tả nghiệp vụ&quot;">​</a></h3><p>Trả lời <strong>LÀM CÁI GÌ và VÌ SAO</strong>. Tham chiếu mẫu: <code>BienSoDep/docs/features/mvp/UC01-danh-sach-tim-kiem/spec.md</code>.</p><p>Gồm: Objective, User Story, Acceptance Criteria, UI/UX, API Contract, Error Handling, Edge Cases, UI States, Test Cases (sơ bộ), Definition of Done, Out of Scope.</p><p><strong>Với mọi feature có UI</strong> (<code>brandhub-web-dashboard</code>, <code>brandhub-mobile-app</code>), spec.md BẮT BUỘC có thêm 2 mục sau trong Acceptance Criteria / UI States — không được bỏ qua:</p><ul><li><strong>Đa ngôn ngữ (i18n):</strong> liệt kê toàn bộ text hiển thị mới sẽ dùng key nào (namespace, vd <code>landing.features.demoLabel</code>), xác nhận key được thêm đồng thời vào <strong>cả</strong><code>vi.json</code> và <code>en.json</code> (key-parallel), không hardcode chuỗi tiếng Việt/Anh trong JSX.</li><li><strong>Light/Dark mode:</strong> xác nhận UI mới hoạt động đúng ở cả 2 theme — dùng token/biến theme hoặc class <code>dark:</code> variant sẵn có, không hardcode màu cố định (hex/rgb) không có cặp dark tương ứng. Nêu rõ nếu có màu đặc thù cần thêm token mới.</li></ul><p><code>plan.md</code> phải liệt kê các file i18n locale sẽ đổi; <code>task.md</code> phải có task riêng &quot;cập nhật vi.json + en.json&quot; và &quot;kiểm tra light/dark mode&quot;; <code>test.md</code> phải có test case xác nhận đổi ngôn ngữ không vỡ UI và chuyển theme không vỡ contrast/màu sắc.</p><h3 id="plan-md-—-ke-hoach-ky-thuat" tabindex="-1">plan.md — Kế hoạch kỹ thuật <a class="header-anchor" href="#plan-md-—-ke-hoach-ky-thuat" aria-label="Permalink to &quot;plan.md — Kế hoạch kỹ thuật&quot;">​</a></h3><p>Trả lời <strong>LÀM THẾ NÀO</strong>. Phân rã giải pháp kỹ thuật dựa trên spec: thành phần, file chạm tới, DB schema thay đổi, luồng dữ liệu, thứ tự build, rủi ro.</p><h3 id="task-md-—-phan-ra-cong-viec" tabindex="-1">task.md — Phân rã công việc <a class="header-anchor" href="#task-md-—-phan-ra-cong-viec" aria-label="Permalink to &quot;task.md — Phân rã công việc&quot;">​</a></h3><p>Trả lời <strong>TỪNG BƯỚC CỤ THỂ</strong>. Checklist thực thi theo thứ tự, mỗi task nhỏ, độc lập, có thể tick. Mỗi task ánh xạ tới phần trong plan.</p><h3 id="test-md-—-kich-ban-kiem-chung" tabindex="-1">test.md — Kịch bản kiểm chứng <a class="header-anchor" href="#test-md-—-kich-ban-kiem-chung" aria-label="Permalink to &quot;test.md — Kịch bản kiểm chứng&quot;">​</a></h3><p>Trả lời <strong>KIỂM TRA GÌ</strong>. Kịch bản test theo Acceptance Criteria trong spec. Nêu test case, input, mong đợi. Dùng làm checklist pass/fail khi hoàn thành.</p><h2 id="_4-tuan-tu-bat-buoc" tabindex="-1">4. Tuần tự bắt buộc <a class="header-anchor" href="#_4-tuan-tu-bat-buoc" aria-label="Permalink to &quot;4. Tuần tự bắt buộc&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec.md  →  plan.md  →  task.md  →  test.md  →  Claude AI đọc &amp; code</span></span>
<span class="line"><span>   ①          ②           ③          ④                ⑤</span></span></code></pre></div><ul><li><strong>①→④ phải hoàn thành theo đúng thứ tự</strong> trước khi ⑤ code.</li><li>Không được nhảy cóc: chưa có spec thì không viết plan; chưa có plan thì không tách task; chưa có task thì không viết test.</li><li>Claude AI (hoặc dev) <strong>chỉ được bắt đầu code sau khi đã đọc đủ cả 4 file</strong>.</li></ul><h2 id="_5-vong-lap-khi-co-sai-sot" tabindex="-1">5. Vòng lặp khi có sai sót <a class="header-anchor" href="#_5-vong-lap-khi-co-sai-sot" aria-label="Permalink to &quot;5. Vòng lặp khi có sai sót&quot;">​</a></h2><p>Nếu trong lúc code (hoặc sau khi code, test fail) phát hiện <strong>sai nghiệp vụ / thiếu sót / hiểu sai yêu cầu</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌─────────────  QUAY LẠI BƯỚC 1  ─────────────┐</span></span>
<span class="line"><span>        │                                             │</span></span>
<span class="line"><span>spec.md (sửa lại cho ĐÚNG) → plan.md (sửa lại) → task.md (sửa lại) → test.md (sửa lại) → code</span></span>
<span class="line"><span>   ①                                ②              ③                ④               ⑤</span></span></code></pre></div><ul><li><strong>Luôn sửa từ <code>spec.md</code> trước</strong> vì spec là gốc rễ của sai lệch.</li><li>Sau khi sửa spec → <strong>refactor lại lần lượt</strong> <code>plan → task → test</code> cho khớp spec mới.</li><li>Không được &quot;vá code&quot; lúc ⑤ rồi bỏ qua việc cập nhật 4 tài liệu. Tài liệu phải là nguồn phản ánh đúng code.</li></ul><h2 id="_6-quy-tac-cho-claude-ai-khi-lam" tabindex="-1">6. Quy tắc cho Claude AI khi làm <a class="header-anchor" href="#_6-quy-tac-cho-claude-ai-khi-lam" aria-label="Permalink to &quot;6. Quy tắc cho Claude AI khi làm&quot;">​</a></h2><ul><li>Đọc đủ 4 file (<code>spec.md</code>, <code>plan.md</code>, <code>task.md</code>, <code>test.md</code>) trước khi viết code.</li><li>Làm đúng theo thứ tự task trong <code>task.md</code>.</li><li>Sau khi code xong, chạy đối chiếu <code>test.md</code> để tự verify.</li><li>Nếu thấy spec/plan không khớp thực tế → <strong>dừng lại</strong>, báo, và làm theo vòng lặp mục 5, không tự ý đổi nghiệp vụ trong lúc code.</li></ul>`,31)])])}const g=n(o,[["render",s]]);export{u as __pageData,g as default};
